/* Source silhouettes are shared by the renderer and fixed-time contact tests. */
#include "side_assets77.h"
#include "side_damage77.h"
static float side_bound77(const Obj*);
static SDL_Texture*sideTexture77,*sideStrength77,*sideDamage77;
static Sprite sideUV77[7];
static int side_index77(const Obj*o,int n){if(organic_context())return 0;if(o->type==4){if(o->variant!=7)return 0;if(n==47)return 5;if(n==74)return 6;if(n==86)return 7;float f=o->power/256.0f;return 5+(f<.5f?0:f<1.5f?1:2);}return o->type==21?1:o->type==7?2:o->type==13?3:o->type==16?4:0;}
static float side_growth77(const Obj*o){if(o->type!=4)return 1;float f=o->power/256.0f;int s=f>=1?1:0;return 1+.42f*(s+smooth_unit(f-s));}
static float side_angle77(const Obj*o){return (o->heading/16.0f+(o->type==4?-90:90))*PI/180;}
static int side_mask_point77(int id,float x,float y){if(x<0||y<0||x>=1||y>=1)return 0;const SideAsset77*a=sideAsset77+id-1;return (a->mask[clamp((int)(y*32),0,31)]>>(clamp((int)(x*64),0,63)))&1;}
static int side_relative_hit77(const Obj*o,float x,float y,float pad){int id=side_index77(o,-1);if(!id)return 0;x*=696.0f/960;y*=960.0f/696;float angle=side_angle77(o),c=cosf(angle),s=sinf(angle),xx=x*c+y*s,yy=-x*s+y*c,scale=side_growth77(o);int first=id,last=id;if(o->type==4){float f=o->power/256.0f;int stage=f>=1?1:0;float blend=smooth_unit(f-stage);first=5+stage+(blend>.999f);last=5+stage+(blend>.001f);}for(int i=first;i<=last;i++){const SideAsset77*a=sideAsset77+i-1;for(int q=0;q<9;q++){static const float offsets[9][2]={{0,0},{1,0},{-1,0},{0,1},{0,-1},{.7f,.7f},{-.7f,.7f},{.7f,-.7f},{-.7f,-.7f}};if(side_mask_point77(i,(xx+offsets[q][0]*pad)/(a->w*scale)+a->ax,(yy+offsets[q][1]*pad)/(a->h*scale)+a->ay))return 1;}}return 0;}
int pc_enemy_side_hit77(const Obj*o,int x,int y,int padding){if(!flight_side_mode()||!side_index77(o,-1))return -1;float dx=(x-o->x)/(float)Q,dy=(y-o->y)/(float)Q,r=side_bound77(o)+padding;if(fabsf(dx)>r||fabsf(dy)>r)return 0;return side_relative_hit77(o,dx,dy,padding);}
int pc_enemy_side_body77(const Obj*o,int ox,int oy){if(!flight_side_mode()||!side_index77(o,-1))return -1;float x=(ex.damagePrevX-ox)/(float)Q,y=(ex.damagePrevY-oy)/(float)Q,xx=(g.px-o->x)/(float)Q,yy=(player_y-o->y)/(float)Q;float dx=xx-x,dy=yy-y,d=dx*dx+dy*dy,u=d>0?fmaxf(0,fminf(1,-(x*dx+y*dy)/d)):0,r=side_bound77(o)+fmaxf(player_hull_rx(),player_hull_ry())+1;if((x+dx*u)*(x+dx*u)+(y+dy*u)*(y+dy*u)>r*r)return 0;int steps=clamp((int)ceilf(hypotf(xx-x,yy-y)/2),1,32);for(int i=0;i<=steps;i++)for(int p=0;p<13;p++){static const float sample[13][2]={{0,0},{1,0},{-1,0},{0,1},{0,-1},{.7f,.7f},{-.7f,.7f},{.7f,-.7f},{-.7f,-.7f},{.5f,0},{-.5f,0},{0,.5f},{0,-.5f}};if(side_relative_hit77(o,x+(xx-x)*i/steps+sample[p][0]*player_hull_rx(),y+(yy-y)*i/steps+sample[p][1]*player_hull_ry(),1))return 1;}return 0;}
void pc_enemy_side_muzzle77(const Obj*o,int*x,int*y,int belly){if(!flight_side_mode())return;int id=side_index77(o,-1);if(!id)return;const SideAsset77*a=sideAsset77+id-1;float u=belly?.6f:a->mx,v=belly?.9f:a->my;if(o->type==4&&belly==2){u=.12f;v=.66f+clamp((*x-o->x)/Q,-75,75)*.0016f;}float scale=side_growth77(o),xx=(u-a->ax)*a->w*scale,yy=(v-a->ay)*a->h*scale,angle=side_angle77(o),c=cosf(angle),s=sinf(angle);*x=o->x+(int)((xx*c-yy*s)*(960.0f/696)*Q);*y=o->y+(int)((xx*s+yy*c)*(696.0f/960)*Q);}

static void side_engine_port77(const Obj*o,int port,float*x,float*y){int id=side_index77(o,-1);if(!id||id>=5)return;const SideAsset77*a=sideAsset77+id-1;float u=.98f,v=id==1?.40f+.18f*port:port&1?.75f:.4f,xx=(u-a->ax)*a->w,yy=(v-a->ay)*a->h,angle=side_angle77(o),c=cosf(angle),s=sinf(angle),tx=o->x/(float)Q+(xx*c-yy*s)*960/(960-264*sideBlend),ty=o->y/(float)Q+(xx*s+yy*c)*696/(696+264*sideBlend);*x+=(tx-*x)*sideBlend;*y+=(ty-*y)*sideBlend;}

static float side_bound77(const Obj*o){if(!flight_side_mode())return 0;int id=side_index77(o,-1);if(!id)return 0;float r=sideMaximumBounds77[id-1];if(o->type==4){float f=o->power/256.0f;int stage=f>=1?1:0;float blend=smooth_unit(f-stage);for(int n=5+stage+(blend>.999f);n<=5+stage+(blend>.001f);n++)r=fmaxf(r,sideMaximumBounds77[n-1]);}return r*side_growth77(o);}
int pc_enemy_side_beam77(const Obj*o){if(!flight_side_mode())return -1;int id=side_index77(o,-1);if(!id)return -1;if(!beam_hits(o->x/Q,o->y/Q,(int)ceilf(side_bound77(o))))return 0;float angle=side_angle77(o),c=cosf(angle),s=sinf(angle),scale=side_growth77(o);int first=id,last=id;if(o->type==4){float f=o->power/256.0f;int stage=f>=1?1:0;float blend=smooth_unit(f-stage);first=5+stage+(blend>.999f);last=5+stage+(blend>.001f);}for(int i=first;i<=last;i++){const SideAsset77*a=sideAsset77+i-1;for(int y=0;y<32;y++)for(int x=0;x<64;x++)if((a->mask[y]>>x)&1){float xx=((x+.5f)/64-a->ax)*a->w*scale,yy=((y+.5f)/32-a->ay)*a->h*scale,wx=o->x/(float)Q+(xx*c-yy*s)*960/696,wy=o->y/(float)Q+(xx*s+yy*c)*696/960;if(wy<player_y/(float)Q-12&&beam_hits((int)wx,(int)wy,1))return 1;}}return 0;}

/* Damage smoke/fire stays on a painted surface, not the old top-view ellipse. */
static int side_damage_point77(const Obj*o,int n,float*x,float*y){if(sideBlend<.5f)return 0;int id=side_index77(o,-1);if(id<5)return 0;const SideAsset77*a=sideAsset77+id-1;n=clamp(n,0,4);int bx=sideDamageCells77[id-1][n][0],by=sideDamageCells77[id-1][n][1];float scale=side_growth77(o)*(1+.004f*sinf(visualTick*.055f+o->variant)),xx=((bx+.5f)/64-a->ax)*a->w*scale,yy=((by+.5f)/32-a->ay)*a->h*scale,angle=side_angle77(o),c=cosf(angle),s=sinf(angle);*x=o->x/(float)Q+(xx*c-yy*s)*960/(960-264*sideBlend);*y=o->y/(float)Q+(xx*s+yy*c)*696/(696+264*sideBlend);return 1;}
